`timescale 1ns/1ps
module tb_axi_ddr_cdc;
 reg cc=0,dc=0,cr=0,dr=0,init=0;always#5 cc=~cc;always#4 dc=~dc;
 reg[3:0]arid=0,awid=0,wid=0;reg[31:0]araddr=0,awaddr=0,wdata=0;reg[7:0]arlen=0,awlen=0;reg[2:0]arsize=2,awsize=2;reg[1:0]arburst=1,awburst=1;reg arvalid=0,rready=1,awvalid=0,wlast=0,wvalid=0,bready=1;wire arready;wire[3:0]rid,bid;wire[31:0]rdata;wire[1:0]rresp,bresp;wire rlast,rvalid,awready,wready,bvalid;
 wire[27:0]maw,mar;wire maw_ap,mar_ap;wire[3:0]mawid,marid,mawlen,marlen;wire mawv,marv;reg mawr=1,marr=1;wire[255:0]mwd;wire[31:0]mws;reg mwready=0;wire[3:0]mwout=0;wire mwlast=1;reg[255:0]mrd=0;reg[3:0]mrid=0;reg mrlast=1,mrv=0;
 axi_ddr_cdc dut(.sys_clk(cc),.sys_resetn(cr),.s_arid(arid),.s_araddr(araddr),.s_arlen(arlen),.s_arsize(arsize),.s_arburst(arburst),.s_arvalid(arvalid),.s_arready(arready),.s_rid(rid),.s_rdata(rdata),.s_rresp(rresp),.s_rlast(rlast),.s_rvalid(rvalid),.s_rready(rready),.s_awid(awid),.s_awaddr(awaddr),.s_awlen(awlen),.s_awsize(awsize),.s_awburst(awburst),.s_awvalid(awvalid),.s_awready(awready),.s_wid(wid),.s_wdata(wdata),.s_wstrb(4'hf),.s_wlast(wlast),.s_wvalid(wvalid),.s_wready(wready),.s_bid(bid),.s_bresp(bresp),.s_bvalid(bvalid),.s_bready(bready),.ddr_clk(dc),.ddr_resetn(dr),.ddr_init_done(init),.m_awaddr(maw),.m_awuser_ap(maw_ap),.m_awuser_id(mawid),.m_awlen(mawlen),.m_awvalid(mawv),.m_awready(mawr),.m_wdata(mwd),.m_wstrb(mws),.m_wready(mwready),.m_wusero_id(mwout),.m_wusero_last(mwlast),.m_araddr(mar),.m_aruser_ap(mar_ap),.m_aruser_id(marid),.m_arlen(marlen),.m_arvalid(marv),.m_arready(marr),.m_rdata(mrd),.m_rid(mrid),.m_rlast(mrlast),.m_rvalid(mrv));
 reg[255:0]mem[0:31];reg wp=0,rp=0;reg[27:0]wa=0,ra=0;
 always@(posedge dc)begin mwready<=0;mrv<=0;if(mawv&&mawr)begin wp<=1;wa<=maw;end;if(wp)begin integer i;for(i=0;i<32;i=i+1)if(mws[i])mem[wa>>3][i*8+:8]<=mwd[i*8+:8];mwready<=1;wp<=0;end;if(marv&&marr)begin rp<=1;ra<=mar;mrid<=marid;end;if(rp)begin mrd<=mem[ra>>3];mrv<=1;rp<=0;end end
 task write1(input[31:0]a,input[31:0]d);begin @(negedge cc);awaddr=a;awid=3;awlen=0;awvalid=1;while(!awready)@(negedge cc);@(negedge cc);awvalid=0;wdata=d;wid=3;wlast=1;wvalid=1;while(!wready)@(negedge cc);@(negedge cc);wvalid=0;wlast=0;while(!bvalid)@(negedge cc);if(bresp) $fatal(1,"write response error");end endtask
 task read1(input[31:0]a,input[31:0]exp);begin @(negedge cc);araddr=a;arid=4;arlen=0;arvalid=1;while(!arready)@(negedge cc);@(negedge cc);arvalid=0;while(!rvalid)@(negedge cc);if(rresp||rdata!==exp||!rlast)$fatal(1,"read mismatch got=%h expected=%h",rdata,exp);end endtask
 initial begin repeat(5)@(posedge cc);cr=1;dr=1;init=1;write1(32'h100,32'hdeadbeef);read1(32'h100,32'hdeadbeef);write1(32'h11c,32'h12345678);read1(32'h11c,32'h12345678);$display("PASS tb_axi_ddr_cdc");$finish;end
endmodule

